const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>n==null?'—':Number(n).toLocaleString('vi-VN',{maximumFractionDigits:1});
let state=null,version=0,user=null,view='overview',period={type:'month',value:10},editing=null,updating=null,busy=false,stale=false;
const roleNames={admin:'Quản trị',manager:'Quản lý bộ phận',contributor:'Nhân viên',viewer:'Người xem'},modeNames={last:'Giá trị cuối kỳ',sum:'Cộng các tháng',average:'Trung bình các tháng'};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
async function req(url,method='GET',body){let r=await fetch(url,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let x=await r.json();if(!r.ok)throw Object.assign(Error(x.error||'Lỗi kết nối'),{status:r.status});return x}
async function sync(){try{let x=await req('/api/workspace');state=x.state?KPI.migrate(x.state):null;version=x.version;stale=false;render();toast('Đã tải dữ liệu mới nhất')}catch(e){toast(e.message)}}
async function mutate(op){if(busy){toast('Đang lưu, vui lòng chờ.');return false}if(stale){toast('Có thay đổi từ người khác. Hãy bấm Đồng bộ trước khi lưu.');return false}busy=true;try{let x=await req('/api/workspace','POST',{version,op});state=KPI.migrate(x.state);version=x.version;render();toast('Đã lưu vào kho chung');return true}catch(e){if(e.status===409)stale=true;toast(e.message);return false}finally{busy=false}}
const manage=k=>user&&(user.role==='admin'||user.role==='manager'&&k.level!=='IID'&&k.team===user.team),write=k=>manage(k)||user?.role==='contributor'&&k.ownerEmail?.toLowerCase()===user.email;
const result=k=>KPI.measure(k,period),score=k=>result(k).score,titlePeriod=()=>period.type==='month'?`Tháng ${period.value}/2027`:`Quý ${period.value}/2027`;
function head(title,desc,create=false){return `<div class="titlebar"><div><div class="eyebrow">KHO KPI CHUNG · ${esc(titlePeriod())} · PHIÊN BẢN ${version}</div><h1>${title}</h1><p>${desc}</p></div>${create&&['admin','manager'].includes(user.role)?'<button class="primary" onclick="openEditor()">+ Tạo KPI mới</button>':''}</div>`}
function badge(k){let n=score(k);return `<span class="badge ${n==null||n<100?'warn':''} ${n!=null&&n<80?'bad':''}">${n==null?'Chưa đủ dữ liệu':n>=100?'Đạt mục tiêu':n<80?'Cần chú ý':'Đang theo dõi'}</span>`}
function warning(){return Object.values(KPI.groups(state.kpis)).filter(ks=>Math.abs(ks.reduce((s,k)=>s+k.weight,0)-100)>.01).map(ks=>`<div class="alert">${esc(KPI.label(ks))}: tổng trọng số ${num(ks.reduce((s,k)=>s+k.weight,0))}%, cần bằng 100%.</div>`).join('')}
function rows(ks){return !ks.length?'<div class="empty">Không có KPI phù hợp.</div>':`<div class="tablewrap"><table><thead><tr><th>KPI / NGƯỜI PHỤ TRÁCH</th><th>CẤP / BỘ PHẬN</th><th>TRỌNG SỐ</th><th>MỤC TIÊU KỲ</th><th>KẾT QUẢ</th><th>HOÀN THÀNH</th><th>THAO TÁC</th></tr></thead><tbody>${ks.map(k=>{let r=result(k);return `<tr><td><strong>${esc(k.name)}</strong><small>${esc(k.owner)}</small><small>${esc(k.ownerEmail||'Chưa giao email')}</small></td><td>${esc(k.level)}<small>${esc(k.team)}</small></td><td>${num(k.weight)}%</td><td>${num(r.target)} ${esc(k.unit)}<small>${esc(modeNames[k.mode])} · ${k.direction==='down'?'↓':'↑'}</small></td><td>${num(r.actual)}<small>${r.coverage}/${r.total} tháng có dữ liệu</small></td><td>${badge(k)}<small>${num(r.score)}%</small></td><td>${write(k)&&period.type==='month'?`<button onclick="openUpdate(${JSON.stringify(k.id).replaceAll('"','&quot;')})">Cập nhật</button>`:''}${manage(k)?` <button onclick="openEditor(${JSON.stringify(k.id).replaceAll('"','&quot;')})">Sửa</button> <button onclick="removeKpi(${JSON.stringify(k.id).replaceAll('"','&quot;')})">Lưu trữ</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(!user)return;if(!state){$('#app').innerHTML=head('Khởi tạo kho KPI chung','Chọn dữ liệu để bắt đầu. Dữ liệu cũ trên trình duyệt được giữ lại.')+(user.role==='admin'?`<div class="guidegrid"><div class="panel"><h2>Chuyển dữ liệu phiên bản cũ</h2><p>Dùng dữ liệu KPI đang lưu trên trình duyệt này để tạo kho chung.</p><button onclick="initialize('local')">Chuyển dữ liệu cũ</button></div><div class="panel"><h2>Bắt đầu mới</h2><p>Kho trống để nhập KPI thực tế, hoặc bộ KPI minh họa có sẵn.</p><button class="primary" onclick="initialize('empty')">Tạo kho trống</button> <button onclick="initialize('sample')">Dùng dữ liệu mẫu</button></div></div>`:'<div class="panel">Quản trị cần khởi tạo kho chung trước.</div>');return}
let ks=state.kpis,groups=KPI.groups(ks);if(view==='overview')$('#app').innerHTML=head('Tổng quan hiệu suất','Cùng một nguồn dữ liệu. Rõ mục tiêu, rõ trách nhiệm.',true)+`<div class="hero"><div><div class="eyebrow">IID · WORKSPACE 2027</div><h2>Mỗi đóng góp kết nối với mục tiêu chung.</h2><p>${esc(user.email)} · ${esc(roleNames[user.role])}${user.team?' · '+esc(user.team):''}</p></div><div class="art">↗</div></div><div class="stats"><div class="card"><small>ĐIỂM TOÀN KHỐI</small><div class="number">${num(KPI.weighted(ks.filter(k=>k.level==='IID'),period))}%</div><p>Trần điểm trọng số: 120%</p></div><div class="card"><small>KPI ĐANG QUẢN LÝ</small><div class="number">${ks.length}</div><p>${Object.keys(groups).length} nhóm mục tiêu</p></div><div class="card"><small>CÓ ĐỦ KẾT QUẢ KỲ</small><div class="number">${ks.filter(k=>score(k)!=null).length}/${ks.length}</div><p>Theo phương pháp của từng KPI</p></div><div class="card"><small>CẦN CHÚ Ý</small><div class="number">${ks.filter(k=>score(k)!=null&&score(k)<80).length}</div><p>Dưới 80% mục tiêu kỳ</p></div></div>${warning()}<div class="panels"><div class="panel"><h2>Điểm tổng hợp theo nhóm</h2>${Object.values(groups).map(a=>{let n=KPI.composite(state,a,period);return `<div class="progressrow"><span>${esc(KPI.label(a))}<small class="mini"> · ${esc(a[0].level)}</small></span><div class="track"><div class="fill" style="width:${Math.min(100,n||0)}%"></div></div><strong>${num(n)}%</strong></div>`}).join('')||'<p>Hãy tạo KPI đầu tiên.</p>'}<p class="mini">Điểm kết hợp IID, bộ phận và cá nhân theo cơ cấu; chỉ tính khi đủ dữ liệu và trọng số.</p></div><div class="panel"><h2>Nhịp quản trị</h2><div class="alert">${ks.filter(k=>score(k)==null).length} KPI chưa đủ kết quả trong kỳ.</div><div class="alert">${state.actions.filter(a=>a.status!=='Hoàn tất').length} việc đang mở.</div><p>Chọn Tháng để cập nhật kết quả; chọn Quý để đánh giá cả kỳ.</p><button onclick="view='review';render()">Đánh giá quý →</button></div></div><div class="sectionspace">${rows(ks.filter(k=>k.level==='IID'))}</div>`;
if(view==='kpis'){$('#app').innerHTML=head('Sổ KPI','Mục tiêu theo kỳ, email người được giao và kết quả dùng chung.',true)+warning()+'<div class="toolbar"><input id="search" placeholder="Tìm KPI, tên hoặc email…"><select id="filterLevel"><option value="">Tất cả cấp</option><option>IID</option><option>Bộ phận</option><option>Cá nhân</option></select><select id="filterTeam"><option value="">Tất cả bộ phận</option>'+[...new Set(ks.map(k=>k.team))].map(t=>`<option>${esc(t)}</option>`).join('')+'</select></div><div id="results"></div>';let filter=()=>{$('#results').innerHTML=rows(ks.filter(k=>[k.name,k.owner,k.ownerEmail,k.team].join(' ').toLowerCase().includes($('#search').value.toLowerCase())&&(!$('#filterLevel').value||k.level===$('#filterLevel').value)&&(!$('#filterTeam').value||k.team===$('#filterTeam').value)))};['search','filterLevel','filterTeam'].forEach(id=>$('#'+id).oninput=filter);filter()}
if(view==='cascade')$('#app').innerHTML=head('Liên kết mục tiêu','IID → Bộ phận → Cá nhân',true)+`<div class="panel"><h2>Cơ cấu điểm tổng hợp</h2><div class="guidegrid">${mixForm('department','Bộ phận',['IID','Bộ phận'],[[30,70],[30,70]])}${mixForm('personal','Cá nhân',['IID','Bộ phận','Cá nhân'],[[20,40],[30,50],[20,40]])}</div></div><div class="sectionspace">${ks.filter(k=>k.level==='IID').map(k=>`<div class="treeitem"><span class="badge">IID</span> ${esc(k.name)}<div class="tree">${ks.filter(c=>c.parent===k.id).map(c=>`<div class="treeitem"><span class="badge">${esc(c.team)}</span> ${esc(c.name)}<div class="tree">${ks.filter(p=>p.parent===c.id).map(p=>`<div class="treeitem">${esc(p.owner)} · ${esc(p.name)}</div>`).join('')}</div></div>`).join('')}</div></div>`).join('')}</div>`;
if(view==='review'){let q=period.type==='quarter'?period.value:Math.ceil(period.value/3),p={type:'quarter',value:q};$('#app').innerHTML=head('Đánh giá quý '+q,'Dữ liệu cả quý được tổng hợp theo cách tính của từng KPI.')+`<div class="alert">Cộng / trung bình cần đủ 3 tháng; giá trị cuối kỳ cần kết quả tháng ${q*3}. Chốt quý sẽ khóa cập nhật dữ liệu và lưu kết quả tại thời điểm chốt.</div>`+Object.entries(groups).map(([key,a],i)=>{let r=state.reviews[q+'|'+key]||{},n=KPI.composite(state,a,p),allowed=user.role==='admin'||user.role==='manager'&&a[0].level!=='IID'&&a[0].team===user.team;return `<div class="panel reviewcard"><div class="paneltitle"><h2>${esc(KPI.label(a))}</h2><span class="badge">${esc(r.status||'Nháp')} · ${num(r.snapshot?.score??n)}%</span></div><p class="mini">${a.length} KPI · ${r.at?'Lưu lúc '+esc(new Date(r.at).toLocaleString('vi-VN'))+' bởi '+esc(r.by):'Chưa lưu đánh giá'} · ${r.snapshot?'Kết quả đã chốt':'Kết quả hiện tại'}</p><textarea id="review${i}" aria-label="Nhận xét ${esc(KPI.label(a))}" ${!allowed||r.status==='Đã đánh giá'?'disabled':''}>${esc(r.note||'')}</textarea>${allowed&&r.status!=='Đã đánh giá'?`<button onclick="reviewSave(${i},${q},'${encodeURIComponent(key).replaceAll("'","%27")}','Nháp')">Lưu nháp</button> <button class="primary" onclick="reviewSave(${i},${q},'${encodeURIComponent(key).replaceAll("'","%27")}','Đã đánh giá')">Chốt đánh giá</button>`:''}${r.status==='Đã đánh giá'&&user.role==='admin'?`<button onclick="reviewSave(${i},${q},'${encodeURIComponent(key).replaceAll("'","%27")}','Nháp')">Mở lại quý</button>`:''}</div>`}).join('')}
if(view==='trend')$('#app').innerHTML=head('Tiến độ 12 tháng','So sánh kết quả từng tháng với mục tiêu đã phân bổ.')+`<div class="tablewrap"><table><thead><tr><th>KPI</th>${Array.from({length:12},(_,i)=>`<th>T${i+1}</th>`).join('')}</tr></thead><tbody>${ks.map(k=>`<tr><td><strong>${esc(k.name)}</strong><small>${esc(modeNames[k.mode])}</small></td>${Array.from({length:12},(_,i)=>{let r=KPI.measure(k,{type:'month',value:i+1});return `<td><span class="badge ${r.score==null?'':r.score<80?'bad':r.score<100?'warn':''}">${num(r.score)}%</span><small>${num(r.actual)} / ${num(r.target)}</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
if(view==='actions'){let can=user.role!=='viewer';$('#app').innerHTML=head('Kế hoạch hành động','Biến phản hồi thành việc có người phụ trách và thời hạn.')+(can?`<form id="actionform" class="panel fields"><label>Việc cần làm<input name="title" required></label><label>Người phụ trách<input name="owner" required value="${esc(user.name)}"></label><label>Email phụ trách<input name="ownerEmail" type="email" required value="${esc(user.email)}"></label><label>Bộ phận<input name="team" required value="${esc(user.team)}"></label><label>Hạn hoàn thành<input name="due" type="date" required></label><button class="primary">Thêm việc</button></form>`:'')+`<div class="sectionspace">${state.actions.map(a=>`<div class="panel reviewcard"><div class="paneltitle"><h2>${esc(a.title)}</h2><span class="badge">${esc(a.status)}</span></div><p>${esc(a.owner)} · ${esc(a.team)} · Hạn ${esc(a.due)}</p>${user.role==='admin'||user.role==='manager'&&a.team===user.team||user.role==='contributor'&&a.ownerEmail===user.email?`<select aria-label="Trạng thái ${esc(a.title)}" onchange="changeAction('${encodeURIComponent(a.id).replaceAll("'","%27")}',this.value)">${['Mới','Đang làm','Hoàn tất'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select>`:''}</div>`).join('')||'<div class="empty">Chưa có việc cần làm.</div>'}</div>`;if(can)$('#actionform').onsubmit=async e=>{e.preventDefault();await mutate({type:'action',action:{...Object.fromEntries(new FormData(e.target)),id:crypto.randomUUID(),status:'Mới'}})}}
if(view==='members'){if(user.role!=='admin'){$('#app').innerHTML=head('Thành viên & quyền','Vai trò hiện tại: '+roleNames[user.role])+'<div class="panel">Liên hệ quản trị để điều chỉnh quyền.</div>';return}$('#app').innerHTML=head('Thành viên & quyền','Phân quyền thao tác trong ứng dụng bằng email đăng nhập ChatGPT.')+`<div class="alert">Thêm thành viên ở đây cấp quyền ứng dụng. Để người mới mở được website, họ còn cần được chủ sở hữu cấp quyền truy cập Sites. Ứng dụng giữ chế độ truy cập riêng theo danh sách.</div><form id="memberform" class="panel fields"><label>Email<input name="email" type="email" required></label><label>Tên hiển thị<input name="name" required></label><label>Vai trò<select name="role"><option value="viewer">Người xem</option><option value="contributor">Nhân viên</option><option value="manager">Quản lý bộ phận</option><option value="admin">Quản trị</option></select></label><label>Bộ phận<input name="team"></label><button class="primary">Lưu / đổi quyền</button></form><div id="memberlist" class="sectionspace">Đang tải…</div><div id="auditlist" class="sectionspace"></div>`;$('#memberform').onsubmit=async e=>{e.preventDefault();try{await req('/api/members','POST',Object.fromEntries(new FormData(e.target)));toast('Đã lưu quyền ứng dụng');render()}catch(e){toast(e.message)}};loadMembers()}
if(view==='guide')$('#app').innerHTML=head('Quy tắc & hướng dẫn','Quản trị KPI 2027 dùng chung trong khối IID.')+`<div class="guidegrid"><div class="panel"><h2>Quyền thao tác</h2><p>Quản trị: toàn bộ KPI, dữ liệu, thành viên và chốt/mở quý.<br>Quản lý: KPI, kết quả, đánh giá thuộc bộ phận của mình.<br>Nhân viên: kết quả KPI giao đúng email và công việc của mình.<br>Người xem: chỉ đọc. Các vai trò đã cấp đều xem sổ KPI chung.</p></div><div class="panel"><h2>Điểm & dữ liệu kỳ</h2><p>Tháng dùng mục tiêu tháng. Quý dùng cộng, trung bình hoặc giá trị cuối kỳ theo cấu hình KPI. Thiếu dữ liệu bắt buộc hoặc trọng số chưa đủ 100% sẽ không có điểm. Trần điểm trọng số 120%.</p></div><div class="panel"><h2>Chuyển dữ liệu cũ</h2><p>Quản trị có thể nhập JSON đã xuất từ bản cũ. KPI cũ giữ cách tính so mục tiêu năm và giá trị cuối kỳ, để không tự thay đổi kết quả. Sau đó chỉnh cách phân bổ theo chính sách thực tế.</p></div><div class="panel"><h2>Dữ liệu dùng chung</h2><p>Mọi thay đổi lưu trên máy chủ. Đồng bộ để lấy dữ liệu mới; ứng dụng chặn ghi đè phiên bản của người khác. Nhật ký máy chủ ghi email, thao tác và thời gian. Xuất JSON để sao lưu.</p></div></div>`;
}
async function initialize(kind){let s;if(kind==='local'){try{s=JSON.parse(localStorage.getItem('iid-kpi-v1'));if(!s)throw Error()}catch{return toast('Trình duyệt này chưa có dữ liệu cũ. Hãy nhập file JSON hoặc dùng dữ liệu mẫu.')}}else s={kpis:kind==='sample'?seed:[],reviews:{},mix:{department:[50,50],personal:[30,40,30]}};try{KPI.validate(s);await mutate({type:'replace',state:KPI.migrate(s)})}catch(e){toast(e.message)}}
function parentOptions(){let f=$('#form'),l=f.elements.level.value;f.elements.parent.innerHTML='<option value="">Không có</option>'+state.kpis.filter(k=>k.id!==editing&&l!=='IID'&&k.level===(l==='Cá nhân'?'Bộ phận':'IID')&&(l!=='Cá nhân'||k.team===f.elements.team.value)).map(k=>`<option value="${esc(k.id)}">${esc(k.name)} · ${esc(k.team)}</option>`).join('');f.elements.parent.required=l!=='IID'}
function openEditor(id){editing=id||null;$('#form').reset();let k=state.kpis.find(k=>k.id===id);$('#formtitle').textContent=k?'Sửa KPI':'Tạo KPI';if(k)for(let n of ['name','level','team','owner','ownerEmail','weight','target','unit','direction','source','frequency','mode','plan'])$('#form').elements[n].value=k[n]??'';else if(user.role==='manager')$('#form').elements.team.value=user.team;parentOptions();if(k)$('#form').elements.parent.value=k.parent||'';$('#editor').showModal()}
$('#form').elements.level.onchange=parentOptions;$('#form').elements.team.onchange=parentOptions;$('#close').onclick=()=>$('#editor').close();$('#form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),old=state.kpis.find(k=>k.id===editing);let k={...d,id:editing||crypto.randomUUID(),target:Number(d.target),weight:Number(d.weight),ownerEmail:d.ownerEmail.toLowerCase().trim(),parent:d.level==='IID'?null:d.parent,updates:old?.updates||{},targets:old?.targets||{}};if(await mutate({type:'kpi',kpi:k}))$('#editor').close()};
async function removeKpi(id){if(confirm('Lưu trữ KPI này? KPI con cần được đổi liên kết trước.'))await mutate({type:'delete',id})}
function openUpdate(id){if(period.type!=='month')return toast('Chọn kỳ tháng để cập nhật.');updating=id;let k=state.kpis.find(k=>k.id===id),u=k.updates[period.value],f=$('#updateform');f.reset();$('#updatename').textContent=`${k.name} · ${titlePeriod()} · ${k.unit}`;f.elements.actual.value=u?.actual??'';f.elements.note.value=u?.note||'';f.elements.periodTarget.value=k.targets[period.value]??'';f.elements.periodTarget.disabled=!manage(k);$('#update').showModal()}
$('#updateform').onsubmit=async e=>{e.preventDefault();let f=e.target,k=state.kpis.find(k=>k.id===updating);if(manage(k)){let value=f.elements.periodTarget.value;let targets={...k.targets};if(value==='')delete targets[period.value];else targets[period.value]=Number(value);if(JSON.stringify(targets)!==JSON.stringify(k.targets)){if(!await mutate({type:'kpi',kpi:{...k,targets}}))return}}if(await mutate({type:'update',id:updating,month:period.value,actual:Number(f.elements.actual.value),note:f.elements.note.value}))$('#update').close()};
function mixForm(key,title,labels,bounds){return `<form onsubmit="saveMix(event,'${key}')"><h3>${title}</h3>${labels.map((l,i)=>`<label>${l} (${bounds[i][0]}–${bounds[i][1]}%)<input name="v${i}" type="number" min="${bounds[i][0]}" max="${bounds[i][1]}" value="${state.mix[key][i]}" required ${user.role!=='admin'?'disabled':''}></label>`).join('')}${user.role==='admin'?'<p><button>Lưu cơ cấu</button></p>':''}</form>`}
async function saveMix(e,key){e.preventDefault();let mix={...state.mix,[key]:[...new FormData(e.target).values()].map(Number)};try{KPI.validate({...state,mix});await mutate({type:'mix',mix})}catch(e){toast(e.message)}}
async function reviewSave(i,q,key,status){if(status==='Đã đánh giá'&&!confirm('Chốt đánh giá và khóa dữ liệu quý này?'))return;await mutate({type:'review',quarter:q,group:decodeURIComponent(key),note:$('#review'+i).value,status})}
async function changeAction(id,status){let a=state.actions.find(a=>a.id===decodeURIComponent(id));await mutate({type:'action',action:{...a,status}})}
async function loadMembers(){try{let [ms,logs]=await Promise.all([req('/api/members'),req('/api/audit')]);if(view!=='members')return;$('#memberlist').innerHTML=`<div class="tablewrap"><table><thead><tr><th>THÀNH VIÊN</th><th>VAI TRÒ</th><th>BỘ PHẬN</th></tr></thead><tbody>${ms.map(m=>`<tr><td>${esc(m.name)}<small>${esc(m.email)}</small></td><td>${esc(roleNames[m.role])}</td><td>${esc(m.team||'Toàn khối')}</td></tr>`).join('')}</tbody></table></div>`;$('#auditlist').innerHTML='<h2>Nhật ký thay đổi · 100 thao tác gần nhất</h2><div class="tablewrap"><table><tbody>'+logs.map(l=>`<tr><td>${esc(new Date(l.at).toLocaleString('vi-VN'))}</td><td>${esc(l.actor)}</td><td>${esc(l.operation)}</td></tr>`).join('')+'</tbody></table></div>'}catch(e){toast(e.message)}}
function periodOptions(){let count=period.type==='month'?12:4;$('#month').innerHTML=Array.from({length:count},(_,i)=>`<option value="${i+1}" ${i+1===period.value?'selected':''}>${period.type==='month'?'Tháng':'Quý'} ${i+1} / 2027</option>`).join('')}
$('#periodType').onchange=e=>{period={type:e.target.value,value:e.target.value==='quarter'?Math.ceil(period.value/3):period.value*3};periodOptions();render()};$('#month').onchange=e=>{period.value=Number(e.target.value);render()};$('#refresh').onclick=sync;document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
function download(text,type,name){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}$('#backup').onclick=()=>{if(state)download(JSON.stringify(state,null,2),'application/json','iid-kpi-shared-2027.json')};$('#export').onclick=()=>{if(!state)return;let cell=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@\-]/,"'$&")+'"';download('\ufeff'+[['KPI','Cấp','Bộ phận','Owner','Email','Trọng số','Kỳ','Mục tiêu kỳ','Thực tế','Điểm %'],...state.kpis.map(k=>{let r=result(k);return[k.name,k.level,k.team,k.owner,k.ownerEmail,k.weight,titlePeriod(),r.target,r.actual,r.score]})].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8','iid-kpi-report.csv')};
$('#import').onchange=async e=>{try{if(user.role!=='admin')throw Error('Chỉ quản trị được nhập dữ liệu.');let s=JSON.parse(await e.target.files[0].text());KPI.validate(s);if(confirm('Thay dữ liệu kho chung bằng bản sao? Hãy xuất bản sao hiện tại trước.'))await mutate({type:'replace',state:KPI.migrate(s)})}catch(e){toast(e.message)}finally{e.target.value=''}};
periodOptions();$('#app').innerHTML='<div class="empty">Đang kết nối kho KPI chung…</div>';(async()=>{try{user=await req('/api/session');$('.avatar').textContent=roleNames[user.role];let x=await req('/api/workspace');state=x.state?KPI.migrate(x.state):null;version=x.version;render()}catch(e){$('#app').innerHTML='<div class="panel"><h1>Truy cập kho KPI</h1><p>'+esc(e.message)+'</p><a href="/signin-with-chatgpt?return_to=%2F" target="_top">Đăng nhập ChatGPT</a></div>'}})();


